def trace(input_data):
    sess = TraceSession(
        algorithm='Insertion Sort (Swap-based)',
        input_data=input_data,
        pseudocode=[
            'Iterate i from 1 to n-1 (growing sorted prefix)',
            'For j from i down to 1, compare arr[j] with arr[j-1]',
            'If arr[j] < arr[j-1], swap them; else break',
            'Return the sorted array'
        ],
    )
    arr = sess.array('nums', input_data['nums'])
    i_ptr = sess.pointer('i', on=arr, idx=0)
    j_ptr = sess.pointer('j', on=arr, idx=0)
    n = len(input_data['nums'])
    for i in range(1, n):
        i_ptr.move(i, reason='Move i to new element')
        for j in range(i, 0, -1):
            j_ptr.move(j, reason='Compare with left neighbor')
            if arr[j] < arr[j-1]:
                arr.highlight(j, role='compared')
                arr.highlight(j-1, role='compared')
                sess.note('Swap because arr[j] < arr[j-1]')
                arr.swap(j, j-1)
                arr.unhighlight(j)
                arr.unhighlight(j-1)
            else:
                sess.note('Already in order, stop')
                break
        sess.note('Element at index ' + str(i) + ' is now sorted')
    answer = arr.to_list()
    sess.result(answer)
    trace = sess.to_trace()
    for event in trace['events']:
        op = event.get('op')
        targets = event.get('targets', [])
        target_ids = [t.get('id', '') for t in targets]
        if op == 'create' and 'nums' in target_ids:
            event['code_line'] = 1
        elif op == 'create' and 'i' in target_ids:
            event['code_line'] = 1
        elif op == 'create' and 'j' in target_ids:
            event['code_line'] = 2
        elif op == 'move' and 'i' in target_ids:
            event['code_line'] = 1
        elif op == 'move' and 'j' in target_ids:
            event['code_line'] = 2
        elif op == 'swap':
            event['code_line'] = 3
        elif op in ('highlight', 'unhighlight'):
            event['code_line'] = 2
        elif op == 'note':
            text = event.get('reason', '') or event.get('text', '')
            if 'swap' in text.lower():
                event['code_line'] = 3
            elif 'in order' in text.lower() or 'sorted' in text.lower():
                event['code_line'] = 2
            else:
                event['code_line'] = 1
        elif op == 'result':
            event['code_line'] = 4
        else:
            event['code_line'] = 1
    return trace
